import React from "react";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let x = 500;
  let y = 500;

  let radius = 100;
  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${
            x - radius
          }, ${y} a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${
            x + radius
          }, ${y} a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x}, ${
            y + radius
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x}, ${
            y - radius
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
    </div>
  );
}

export default LoadingPage;
